1	// The Agent message box (the Composer proposal on the "JusPrin v2" canvas):
2	// one bordered box holding the staged attachments, the text field, and a
3	// toolbar with + on the left and Send on the right. The field starts one
4	// line high and grows a line at a time up to component.composer.maxLines,
5	// then scrolls inside the box; the toolbar stays.
6	//
7	// Input rules from the handoff: Enter sends, Shift+Enter inserts a newline,
8	// and Enter during IME composition accepts the composition without sending.
9	// Normal selection, clipboard, and focus behavior are left to the browser
10	// engine. The in-progress draft is reported (debounced) so the host can keep
11	// it with the project's saved state; reconnecting restores it via initialText.
12	//
13	// Attachments enter through the + menu's file picker, drag-and-drop, or
14	// pasting an image; staged attachments render as removable rows, and a
15	// message may be sent with attachments and no text. The host owns decoding
16	// and storage -- the composer only hands it files.
17	
18	import { ChangeEvent, ClipboardEvent, DragEvent, KeyboardEvent, ReactNode, useEffect, useLayoutEffect, useRef, useState } from 'react';
19	import { AttachmentInfo, AttachmentPickKind, AttachmentSource, ChatModelChoice, ModelCatalogPayload } from '../bridge/protocol';
20	import { composerInputMaxHeight } from '../tokens';
21	import { AttachmentChip } from './AttachmentChip';
22	import { ActionMenu } from './ChatNavigation';
23	import { ModelPickers } from './ModelPickers';
24	
25	// What the + menu offers: the four kinds the design names. In the app each
26	// opens the operating system's file dialog through the host, which filters
27	// it to the extensions it files under that kind. `accept` is the browser
28	// input's copy of the same lists, used only where the page runs without
29	// that host (review pages, tests). Text and SVG files are accepted too, by
30	// dropping them.
31	export const ATTACHMENT_CHOICES: readonly { label: string; kind: AttachmentPickKind; accept: string }[] = [
32	  { label: 'Photo or image', kind: 'image', accept: '.png,.jpg,.jpeg,.gif,.webp' },
33	  { label: '3D model (STL, 3MF, STEP)', kind: 'model',
34	    accept: '.stl,.3mf,.step,.stp,.obj,.amf,.oltp,.drc,.ply,.usd,.usda,.usdc,.usdz,.abc' },
35	  { label: 'G-code', kind: 'gcode', accept: '.gcode,.g,.gco' },
36	  { label: 'Document (PDF)', kind: 'pdf', accept: '.pdf' },
37	];
38	
39	interface Props {
40	  disabled: boolean;
41	  disabledReason?: string;
42	  streaming: boolean;
43	  initialText?: string;
44	  attachments: AttachmentInfo[]; // staged attachments only
45	  onSend: (text: string) => void;
46	  onStop: () => void;
47	  onAttachFiles: (files: File[], source: AttachmentSource) => void;
48	  // Opens the host's own file dialog for one kind; absent where the host
49	  // cannot, and the browser's file input is used instead.
50	  onPickFiles?: (kind: AttachmentPickKind) => void;
51	  onRemoveAttachment: (id: string) => void;
52	  onDraftChange?: (text: string) => void;
53	  draftDebounceMs?: number;
54	  // Fired on the keystroke itself, not on the debounced draft save. Anything
55	  // covering the thread uses this to get out of the way immediately.
56	  onTyping?: () => void;
57	  // A likely answer to what was just asked, rather than the standing
58	  // invitation. The printer panel writes one per turn.
59	  placeholder?: string;
60	  // Labelled "Photo" instead of the + menu: in the printer panel a picture
61	  // is a primary way to say which printer this is, not an extra.
62	  photoButton?: boolean;
63	  // What the band says above the field when the field cannot be used as it
64	  // is: the notice on an earlier chat, or a recovery alert.
65	  notice?: ReactNode;
66	  // False where nothing can be attached at all, so the action is left out
67	  // rather than shown disabled: a read-only shell has only its field and Send.
68	  attachable?: boolean;
69	  // The chat's model and thinking pickers, where the host offers them.
70	  models?: ModelCatalogPayload;
71	  chatModel?: ChatModelChoice;
72	  onChooseModel?: (choice: ChatModelChoice) => void;
73	}
