75	export function Composer({
76	  disabled,
77	  disabledReason,
78	  streaming,
79	  initialText,
80	  attachments,
81	  onSend,
82	  onStop,
83	  onAttachFiles,
84	  onPickFiles,
85	  onRemoveAttachment,
86	  onDraftChange,
87	  draftDebounceMs = 300,
88	  onTyping,
89	  placeholder,
90	  photoButton,
91	  notice,
