103	  const field = useRef<HTMLTextAreaElement>(null);
104	  const choices = useRef<HTMLDivElement>(null);
105	  const [narrow, setNarrow] = useState(false);
106	
107	  // Grow the field to its text, up to the line limit; past it the field
108	  // scrolls. A field that is not laid out (inside a hidden view) measures 0
109	  // and keeps its height until its text next changes.
110	  useLayoutEffect(() => {
111	    const element = field.current;
112	    if (!element) return;
113	    const previous = element.style.height;
114	    element.style.height = 'auto';
115	    const content = element.scrollHeight;
116	    element.style.height = content > 0 ? `${Math.min(content, composerInputMaxHeight())}px` : previous;
117	  }, [text]);
118	
119	  // A narrow pane: when the choices at full length do not fit beside Send,
120	  // the thinking picker drops "Thinking:", and the model picker's name is
