# Serves the instrumented Agent page, records what it reports, and stands in
# for the model: canned OpenAI Responses streams, so no provider is called.
import json, sys, time
from http.server import ThreadingHTTPServer, BaseHTTPRequestHandler
from urllib.parse import unquote

HERE = sys.argv[1]
LOG = open(f'{HERE}/page.log', 'a', buffering=1)


def sse(event):
    return f'event: message\ndata: {json.dumps(event)}\n\n'.encode()


class Handler(BaseHTTPRequestHandler):
    def log_message(self, *args):
        pass

    def do_GET(self):
        if self.path.startswith('/log?'):
            LOG.write(f'{time.strftime("%H:%M:%S")} {unquote(self.path[5:])}\n')
            self.send_response(204); self.end_headers(); return
        if self.path.startswith('/page.html'):
            body = open(f'{HERE}/web/page.html', 'rb').read()
            self.send_response(200); self.send_header('Content-Type', 'text/html'); self.end_headers()
            self.wfile.write(body); return
        if self.path.startswith('/v1/models'):
            body = json.dumps({'data': [{'id': 'gpt-5.4-mini'}]}).encode()
            self.send_response(200); self.send_header('Content-Type', 'application/json'); self.end_headers()
            self.wfile.write(body); return
        self.send_response(404); self.end_headers()

    def do_POST(self):
        body = self.rfile.read(int(self.headers.get('Content-Length', 0))).decode(errors='replace')
        if 'It stopped' in body:
            reply = 'Thanks, that helps.'
        elif 'my print failed' in body:
            reply = 'What happened?\nChoices: It stopped | Not sure'
        else:
            reply = 'Failed print'
        LOG.write(f'{time.strftime("%H:%M:%S")} MODEL {self.path} -> {reply!r}\n')
        self.send_response(200); self.send_header('Content-Type', 'text/event-stream'); self.end_headers()
        self.wfile.write(sse({'type': 'response.output_text.delta', 'delta': reply}))
        self.wfile.write(sse({'type': 'response.completed', 'response': {'output': []}}))


ThreadingHTTPServer(('127.0.0.1', int(sys.argv[2])), Handler).serve_forever()

